<script setup lang="ts">import {onMounted,watch,ref,computed} from 'vue';import {useStudies} from '../stores/studies';import {useMeasurements} from '../stores/measurements';import {useQuality} from '../stores/quality';import {useAuth} from '../stores/auth';import {useTask} from '../hooks/useTask';import {request} from '../api/client';import {grades,noticeStatus} from '../constants/enums';import type {Treatment,Reading} from '../types/domain';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StudySelect from '../components/StudySelect.vue';const study=useStudies(),data=useMeasurements(),quality=useQuality(),auth=useAuth(),{error,busy,perform}=useTask(),editT=ref<Treatment|null>(null),editR=ref<Reading|null>(null),filter=ref(0),message=ref(''),noticeMessage=ref(''),revokeTarget=ref<number|null>(null);const visible=computed(()=>data.readings.filter(r=>!filter.value||r.treatment_id===filter.value));const excluded=computed(()=>data.readings.filter(r=>r.quality?.excluded));const activeNotices=computed(()=>quality.notices.filter(n=>n.status==='active'));const historicNotices=computed(()=>quality.notices.filter(n=>n.status!=='active'));onMounted(()=>perform(async()=>{await study.load();await Promise.all([data.load(study.selected),quality.load(study.selected)])}));watch(()=>study.selected,id=>{editT.value=null;editR.value=null;filter.value=0;message.value='';noticeMessage.value='';revokeTarget.value=null;perform(async()=>{await data.load(id);await quality.load(id)})});async function saveT(e:Event){const f=new FormData(e.target as HTMLFormElement);await data.saveTreatment({...Object.fromEntries(f),study_id:study.selected},study.selected,editT.value?.id);editT.value=null;message.value='工艺口径已保存。'}async function saveR(e:Event){const f=new FormData(e.target as HTMLFormElement);await data.saveReading({...Object.fromEntries(f),study_id:study.selected,treatment_id:Number(f.get('treatment_id')),grade:Number(f.get('grade'))},study.selected,editR.value?.id);editR.value=null;message.value='独立试样等级已保存；历史快照保持原样。'}async function issueNotice(e:Event){const form=e.target as HTMLFormElement,f=new FormData(form);const raw=String(f.get('codes')||'').split(/[\s,，]+/).map(s=>s.trim()).filter(Boolean);if(!raw.length)throw new Error('请填写至少一个独立试样编号（可跨研究）。');const items=[];const seen=new Set();const cache:Record<number,Set<string>>={};for(const token of raw){let sid=study.selected,code=token;const m=token.match(/^([^/:]+)[/:]([^/:]+)$/);if(m){const st=study.items.find(x=>x.code===m[1]);if(!st)throw new Error('未知研究编号：'+m[1]);sid=st.id;code=m[2]}if(!cache[sid])cache[sid]=new Set((await request<{specimen_code:string}[]>('/readings?study_id='+sid)).map(r=>r.specimen_code));if(!cache[sid].has(code))throw new Error('研究 '+sid+' 中不存在试样 '+code);const key=sid+':'+code;if(seen.has(key))throw new Error('清单中重复试样：'+code);seen.add(key);items.push({study_id:sid,specimen_code:code})}const result=await quality.issue({title:f.get('title'),reason:f.get('reason'),items});noticeMessage.value='质量通告已发布；'+items.length+'份试样失效'+(result.invalidated_run_ids.length?('，已停用依据任务 #'+result.invalidated_run_ids.join('、#')):'')+'。撤销不会恢复旧依据，只能新建检验。';(form.elements.namedItem('codes') as HTMLTextAreaElement).value='';(form.elements.namedItem('title') as HTMLInputElement).value='';(form.elements.namedItem('reason') as HTMLTextAreaElement).value='';await data.load(study.selected)}async function revokeNotice(e:Event){const form=e.target as HTMLFormElement,f=new FormData(form);await quality.revoke(Number(revokeTarget.value),String(f.get('reason')));const id=revokeTarget.value;revokeTarget.value=null;noticeMessage.value='通告 #'+id+' 已撤销。重叠通告全部撤销后，新检验才会重新纳入这些试样；旧结果与批准说明仍可查但不再分发。';await data.load(study.selected)}const name=(id:number)=>data.treatments.find(t=>t.id===id)?.name;const noticeTitles=(ids:number[])=>ids.map(id=>'#'+id+' '+((quality.notices.find(n=>n.id===id)?.title)||'')).join('；');</script><template><PageHeading no="02" title="来源与口径" sub="独立试样逐份核对；质量通告按试样清单跨研究发布。失效试样仍保留在来源台账，只是不再进入新检验。"/><StudySelect/><ErrorNotice :error="error"/><p v-if="message" class="success" role="status">{{message}}</p><p v-if="noticeMessage" class="success" role="status">{{noticeMessage}}</p><div class="data-spread"><section><h2 class="ruled-title">预定义工艺 <small>{{data.treatments.length}}组 / 全部进入检验</small></h2><article class="treatment-entry" v-for="t in data.treatments" :key="t.id"><div><small>{{t.code}}</small><h3>{{t.name}}</h3><p>{{t.process_note}}</p><b>{{data.readings.filter(r=>r.treatment_id===t.id).length}}份独立试样</b></div><button v-if="auth.canEdit" class="small-button" @click="editT=t">编辑</button></article><details v-if="auth.canEdit" class="edit-fold" :open="!!editT"><summary>{{editT?'编辑工艺口径':'＋ 登记工艺'}}</summary><form :key="editT?.id||'new'" @submit.prevent="e=>perform(()=>saveT(e))"><label>工艺编号<input name="code" :value="editT?.code" minLength="2" required/></label><label>工艺名称<input name="name" :value="editT?.name" minLength="2" required/></label><label>工艺与独立单位说明<textarea name="process_note" :value="editT?.process_note"/></label><button :disabled="busy">保存工艺</button><button v-if="editT" type="button" @click="editT=null">取消</button></form></details><aside class="margin-note">每组至少5份，2–5组。试样ID唯一只能防止显式重复，不能证明不存在批次相关；独立性需由制备和抽样设计保障。失效试样不会从台账删除，也不改写任何历史快照。</aside></section><section><div class="section-line"><h2>等级来源台账</h2><label class="inline-select">工艺<select aria-label="筛选工艺" v-model.number="filter"><option :value="0">全部预定义工艺</option><option v-for="t in data.treatments" :value="t.id" :key="t.id">{{t.code}} {{t.name}}</option></select></label></div><details v-if="auth.canEdit" class="edit-fold" :open="!!editR"><summary>{{editR?'编辑 '+editR.specimen_code:'＋ 录入一份独立试样'}}</summary><form class="form-grid" :key="editR?.id||'new'" @submit.prevent="e=>perform(()=>saveR(e))"><label>独立试样编号<input name="specimen_code" :value="editR?.specimen_code" required minLength="2"/></label><label>所属工艺<select name="treatment_id" :value="editR?.treatment_id||data.treatments[0]?.id"><option v-for="t in data.treatments" :value="t.id" :key="t.id">{{t.code}} {{t.name}}</option></select></label><label>形成等级<select name="grade" :value="editR?.grade||1"><option v-for="g in grades" :key="g" :value="g">等级 {{g}}</option></select></label><label>来源说明<input name="source_note" :value="editR?.source_note"/></label><div class="button-row"><button class="primary" :disabled="busy||!data.treatments.length">保存等级</button><button v-if="editR" type="button" @click="editR=null">取消编辑</button></div></form></details><div class="table-scroll"><table><thead><tr><th>独立试样</th><th>工艺</th><th>形成等级</th><th>证据状态</th><th v-if="auth.canEdit"/></tr></thead><tbody><tr v-for="r in visible" :key="r.id" :class="{'excluded-row':r.quality?.excluded}"><td>{{r.specimen_code}}<small>{{r.source_note}}</small></td><td>{{name(r.treatment_id)}}</td><td class="grade-value">{{r.grade}}</td><td><span v-if="r.quality?.excluded" class="status rejected">失效 · 不入新检验</span><span v-else class="status completed">可用</span><small v-if="r.quality?.excluded">{{noticeTitles(r.quality.notice_ids)}}</small></td><td v-if="auth.canEdit"><button class="small-button" @click="editR=r">编辑</button></td></tr></tbody></table></div><p v-if="!visible.length" class="empty">先登记工艺，再为每组录入至少5份独立试样。空组会保留并导致检验失败。</p><p v-if="excluded.length" class="muted">本研究 {{excluded.length}} 份失效：{{excluded.map(r=>r.specimen_code).slice(0,12).join('、')}}{{excluded.length>12?'…':''}}。失效试样仍在台账可见，但会被新检验排除并冻结排除依据。</p></section><section class="notice-spread"><h2 class="ruled-title">质量通告 <small>本页 {{data.readings.length}}份 / 失效 {{excluded.length}}份</small></h2><p class="muted">通告按研究+试样编号发布；清单可混入其他研究的试样，用 研究编号/试样编号 标记（如 QN-NEAR/QN-NEAR-T1-001），不带前缀则属于当前研究。试样只要仍被任一重叠的有效通告覆盖，就保持失效。</p><details v-if="auth.user?.role==='admin'" class="edit-fold"><summary>＋ 按试样清单发布通告</summary><form @submit.prevent="e=>perform(()=>issueNotice(e))"><label>通告标题<input name="title" required minLength="2" maxLength="160" placeholder="如：2026-11-15 批次污染"/></label><label>失效试样编号（每行或逗号分隔）<textarea name="codes" rows="4" required placeholder="QN-SHIFT-T1-004&#10;QN-SHIFT-T2-011&#10;QN-NEAR/QN-NEAR-T1-001（跨研究）"></textarea></label><label>原因与复检影响<textarea name="reason" required minLength="10" maxLength="1000"/></label><button class="primary" :disabled="busy">发布通告并停用受影响依据</button></form></details><p v-else class="muted">仅复检负责人可发布或撤销质量通告。</p><div class="table-scroll"><table><thead><tr><th>通告</th><th>状态</th><th>试样</th><th>原因 / 撤销</th></tr></thead><tbody><tr v-for="n in quality.notices" :key="n.id" :class="{'excluded-row':n.status==='active'}"><td><b>#{{n.id}} · {{n.title}}</b><small>发布 {{n.issued_by||'—'}}</small></td><td><span :class="['status',n.status==='active'?'rejected':'completed']">{{noticeStatus[n.status]}}</span></td><td><small v-for="i in n.items" :key="i.study_id+'-'+i.specimen_code" class="block-small">{{i.specimen_code}}<span v-if="i.treatment_code"> · {{i.treatment_code}}</span><small class="inline-small">{{i.study_code||('研究'+i.study_id)}}</small></small></td><td><span>{{n.reason}}</span><small v-if="n.status==='active'&&auth.user?.role==='admin'" class="block-small"><button class="small-button" @click="revokeTarget=n.id">撤销此通告</button></small><small v-else-if="n.status!=='active'" class="block-small">撤销人 {{n.revoked_by}}：{{n.revocation_reason}}</small><small class="block-small">受影响依据：{{n.affected_run_ids.length?n.affected_run_ids.map(i=>'#'+i).join('、'):'无（发布时无冻结输入命中）'}}</small><form v-if="revokeTarget===n.id" @submit.prevent="e=>perform(()=>revokeNotice(e))"><label>撤销原因（至少5字）<textarea name="reason" required minLength="5" maxLength="1000"/></label><div class="button-row"><button :disabled="busy">确认撤销</button><button type="button" @click="revokeTarget=null">取消</button></div></form></td></tr></tbody></table></div><p v-if="!quality.notices.length" class="empty">尚无质量通告。被确认污染的试样需先发布通告，才能让新检验排除并停用旧依据。</p><p v-if="historicNotices.length&&!activeNotices.length" class="muted">当前研究没有有效通告；历史通告仍保留在留痕中。</p></section></div></template>
